  $nutjson${"slug": "nutrition", "title": "Nutrition", "description": "This course prepares health-professions students to understand nutrients, food, metabolism, dietary patterns, nutrition assessment, nutrition counseling, chronic disease diet therapy, nutrition support, food safety, culture, food security, and community nutrition. Students learn to use evidence responsibly and translate nutrition science into practical, equitable, patient-centered education and care coordination.", "topics": [{"id": "d24b9f5b-0bd6-4cc5-9346-bf0075aec9c6", "type": "topic", "title": "Nutrition science, dietary guidance, and evidence literacy", "description": "Learn how nutrition recommendations are made, how to evaluate claims, and how to use current guidelines responsibly.", "children": [{"id": "3cad41dc-33d8-4c3f-97a3-01619382be94", "type": "subtopic", "title": "Nutrition science and scope", "description": "Students learn what nutrition can and cannot claim, and why food, biology, behavior, and environment must be considered together.", "children": [{"id": "74f732d7-a965-4577-843c-32b97dc9390a", "type": "concept", "title": "Nutrients, foods, dietary patterns, and health outcomes"}, {"id": "2f6858f5-8854-4b34-b0b2-c46d07385a27", "type": "concept", "title": "Essential nutrients and deficiency/toxicity concepts"}, {"id": "27b59a4a-2512-4e8d-b4ca-43fafd4ee920", "type": "concept", "title": "Clinical, public health, and wellness roles"}]}, {"id": "cf9abc4f-9a09-4a4c-a535-97b1ca5ea229", "type": "subtopic", "title": "Current dietary guidance", "description": "This subtopic teaches students to use guidance as a flexible framework rather than a rigid prescription.", "children": [{"id": "3c8fa93c-ccaf-450b-bb64-3706f8327f5c", "type": "concept", "title": "Dietary Guidelines for Americans, 2025-2030"}, {"id": "63a15d6c-97f8-4d94-ac97-317cfd3f4def", "type": "concept", "title": "Food groups, nutrient density, and dietary patterns"}, {"id": "bc90f1f9-1cf2-4466-b267-05d6535e784e", "type": "concept", "title": "Cultural, budgetary, and preference adaptation"}]}, {"id": "63146f15-0778-4ba7-932d-dd966961b986", "type": "subtopic", "title": "Evidence literacy and misinformation", "description": "Students learn to judge nutrition claims with appropriate skepticism and compassion.", "children": [{"id": "5adc5647-ff17-4cf2-83b2-ce41ee231fa2", "type": "concept", "title": "Hierarchy of evidence and study designs"}, {"id": "f579c300-58ed-41bf-97ac-95c768525347", "type": "concept", "title": "Correlation, causation, confounding, and bias"}, {"id": "586f011f-a77f-474f-b27e-a228b3170e68", "type": "concept", "title": "Influencers, supplements, fad diets, and media claims"}]}]}, {"id": "2535e7da-2b2e-473f-b24f-c6e1eb9f3cbd", "type": "topic", "title": "Digestion, absorption, metabolism, and food composition", "description": "Connect foods to nutrients, absorption, metabolism, and physiologic function.", "children": [{"id": "e67f833d-5055-439b-808e-4d10480b5e13", "type": "subtopic", "title": "Digestion and absorption", "description": "Students learn how foods become absorbable nutrients and how GI function affects nutritional status.", "children": [{"id": "423865a6-2edf-4481-9ebd-7b2943e2ba4d", "type": "concept", "title": "GI anatomy and motility"}, {"id": "66c5c768-a655-47a6-83ff-24b8f1114479", "type": "concept", "title": "Enzymes, bile, transporters, and microbiome roles"}, {"id": "5242f08a-4953-416a-be25-7c3b01d814aa", "type": "concept", "title": "Malabsorption, intolerance, and GI symptoms"}]}, {"id": "fa868156-4c3c-456c-b420-74067fd1cc0f", "type": "subtopic", "title": "Metabolic pathways", "description": "This subtopic connects nutrients to energy, storage, synthesis, and physiologic function.", "children": [{"id": "c4ea3c0f-01d9-4e20-a21f-789f3c6e5edc", "type": "concept", "title": "Glycolysis, glycogen, lipolysis, beta-oxidation, and amino acid metabolism"}, {"id": "d90d4b50-919d-4fc2-883c-cbb5db71abc6", "type": "concept", "title": "Fed, fasting, stress, and illness states"}, {"id": "d97b0f60-526f-4f0a-ac69-bd00b07a8291", "type": "concept", "title": "Hormonal regulation by insulin, glucagon, cortisol, and catecholamines"}]}, {"id": "317ec3a1-aff9-412e-aa4b-6f15dbcd7656", "type": "subtopic", "title": "Food composition and labels", "description": "Students learn to read foods as complex mixtures of nutrients, ingredients, processing, and claims.", "children": [{"id": "e3ff4c7e-46df-431c-9def-af9d550c9009", "type": "concept", "title": "FoodData Central and nutrient databases"}, {"id": "de101167-f538-4eb4-b5c1-6387f54d95d1", "type": "concept", "title": "Nutrition Facts label and ingredient lists"}, {"id": "caf8385b-8607-4860-b93f-3c118346d05f", "type": "concept", "title": "Processing, additives, fortification, and reformulation"}]}]}, {"id": "1ecc4206-9e04-4d4d-b3a1-5317da3cd03d", "type": "topic", "title": "Macronutrients: carbohydrates, protein, fats, and dietary patterns", "description": "Understand macronutrient roles, food sources, quality, and clinical relevance.", "children": [{"id": "23f92d56-d592-43a5-8766-46e02b60119b", "type": "subtopic", "title": "Carbohydrates and fiber", "description": "Students learn how carbohydrate quality affects energy, glycemia, GI health, and dietary patterns.", "children": [{"id": "6fa5aa91-b9b8-4a38-866c-f43efbd65a7f", "type": "concept", "title": "Sugars, starches, fiber, and whole-food sources"}, {"id": "3aeaaf10-15e6-4216-8788-f8efce9c4022", "type": "concept", "title": "Glycemic response and diabetes relevance"}, {"id": "90032c6e-72bf-4463-9450-ffade8083f68", "type": "concept", "title": "Fiber, gut health, satiety, and cardiometabolic risk"}]}, {"id": "e43bae7f-2ad2-41ab-a798-ea296cd707ad", "type": "subtopic", "title": "Protein", "description": "This subtopic covers protein needs, quality, timing, and clinical relevance.", "children": [{"id": "6cdaf17b-2086-4da1-af29-6b5581b1a83a", "type": "concept", "title": "Amino acids, protein quality, and complementary proteins"}, {"id": "d3c6ff53-5f6a-4a77