ium"}, {"id": "351f2c52-6856-445b-911f-7057c67444eb", "type": "concept", "title": "Sodium, potassium, chloride, phosphorus"}, {"id": "2fd53a2e-2ce2-495d-a0ce-b6df19777c85", "type": "concept", "title": "Hydration, acid-base balance, and clinical monitoring"}]}, {"id": "666621f3-48b5-41cb-9d9b-84f3715fee01", "type": "subtopic", "title": "Supplements and safety", "description": "Students learn to evaluate supplement claims and risks using reliable sources.", "children": [{"id": "4399cd51-d9bd-429e-bc78-623fabb5b916", "type": "concept", "title": "RDA, AI, UL, deficiency, and toxicity"}, {"id": "66c4ce9e-a7a3-4154-a122-1457a2fa803b", "type": "concept", "title": "Drug-nutrient and nutrient-nutrient interactions"}, {"id": "4f9f73b3-12c1-468e-a903-f91339cc15bb", "type": "concept", "title": "NIH ODS fact sheets and counseling boundaries"}]}]}, {"id": "2606f0b7-dd7f-464c-9e15-125dd80de775", "type": "topic", "title": "Energy balance, body composition, weight, and metabolic health", "description": "Evaluate energy needs, weight change, metabolic health, and respectful approaches to body-size diversity.", "children": [{"id": "bad689e2-60ce-4596-b1b7-20d626fd0b3a", "type": "subtopic", "title": "Energy needs and balance", "description": "Students learn how intake, expenditure, and physiology interact without reducing nutrition to calories alone.", "children": [{"id": "1234d5a6-ebce-4da6-a061-a79c3b35e555", "type": "concept", "title": "Basal metabolism, thermic effect, activity, and adaptive changes"}, {"id": "c51fce3c-6172-4ab6-8e93-b237d97f85e1", "type": "concept", "title": "Energy estimation methods"}, {"id": "a72f08db-d9d5-4766-b216-5c006615e304", "type": "concept", "title": "Weight gain, loss, maintenance, and plateaus"}]}, {"id": "9d187b79-74c7-42ce-bd8a-ab3b409297ae", "type": "subtopic", "title": "Body composition and metabolic health", "description": "This subtopic separates body size from health behaviors while teaching useful assessment tools.", "children": [{"id": "0330e